using System.Security.Claims;
using System.Text.Json;
using EduForge.Domain;
using EduForge.Infrastructure;
using EduForge.Application;
using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;
public record UpdateCopyInput(Guid Revision,bool PreserveLocal);
public static class CopyTrackingEndpoints {
 static Guid Owner(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public static void MapCopyTracking(this WebApplication app){
 var routes=app.MapGroup("/api/copies").RequireAuthorization();
 routes.MapGet("/{kind}/{copyId:guid}",async(string kind,Guid copyId,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{var reference=await db.CopyReferences.AsNoTracking().SingleOrDefaultAsync(x=>x.CopyId==copyId&&x.Kind==kind&&x.TeacherId==Owner(user),ct);if(reference is null)return Results.NoContent();if(kind=="material"){var p=await ContentSharing.PublicMaterials(db).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==reference.SourceId,ct);return Results.Ok(new{Available=p!=null,HasUpdate=p!=null&&p.Revision!=reference.SourceRevision,Revision=p?.Revision,Content=p is null?"":MaterialText.Extract(p.Content),CurrentContent=MaterialText.Extract(await db.Materials.Where(x=>x.Id==copyId&&x.TeacherId==Owner(user)).Select(x=>x.Content).SingleAsync(ct)),Title=p?.Title});}var test=await ContentSharing.PublicTests(db).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==reference.SourceId,ct);var data=test is null?null:JsonSerializer.Deserialize<SaveQuiz>(test.Snapshot);return Results.Ok(new{Available=test!=null,HasUpdate=test!=null&&test.Revision!=reference.SourceRevision,Revision=test?.Revision,Title=test?.Title,CurrentContent=string.Join("\n",await db.Questions.Where(x=>x.QuizId==copyId).OrderBy(x=>x.Position).Select(x=>x.Text).ToListAsync(ct)),Content=data is null?"":string.Join("\n",data.Questions.Select(q=>$"{q.Text} ({q.Points} баллов)"))});});
 routes.MapPost("/{kind}/{copyId:guid}/update",async(string kind,Guid copyId,UpdateCopyInput input,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{var owner=Owner(user);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var reference=await db.CopyReferences.SingleOrDefaultAsync(x=>x.CopyId==copyId&&x.Kind==kind&&x.TeacherId==owner,ct);if(reference is null)return Results.NotFound();if(kind=="material"){var p=await ContentSharing.PublicMaterials(db).SingleOrDefaultAsync(x=>x.Id==reference.SourceId,ct);var local=await db.Materials.SingleOrDefaultAsync(x=>x.Id==copyId&&x.TeacherId==owner,ct);if(p is null||local is null)return Results.NotFound();if(p.Revision!=input.Revision)return Results.Conflict(new{message="Оригинал изменился. Обновите предпросмотр."});var baseline=JsonSerializer.Deserialize<PublishedMaterial>(reference.Baseline)!;var changed=local.Content!=baseline.Content||local.Title!=baseline.Title||local.Subject!=baseline.Subject||local.Level!=baseline.Level||local.Language!=baseline.Language;if(changed&&!input.PreserveLocal)return Results.Conflict(new{message="В копии есть ваши изменения. Включите сохранение текущей версии отдельным материалом."});if(changed)db.Materials.Add(new Material{TeacherId=owner,Title=(local.Title+" — моя версия")[..Math.Min((local.Title+" — моя версия").Length,200)],Subject=local.Subject,Content=local.Content,Level=local.Level,Language=local.Language});local.Title=p.Title;local.Subject=p.Subject;local.Content=await MaterialMediaCopies.Clone(p.Content,owner,db,ct);local.Level=p.Level;local.Language=p.Language;local.UpdatedAt=DateTimeOffset.UtcNow;reference.SourceRevision=p.Revision;reference.Baseline=MaterialMediaCopies.Baseline(p,local.Content);}else if(kind=="test"){var p=await ContentSharing.PublicTests(db).SingleOrDefaultAsync(x=>x.Id==reference.SourceId,ct);var local=await db.Quizzes.Include(x=>x.Questions).ThenInclude(x=>x.Options).SingleOrDefaultAsync(x=>x.Id==copyId&&x.TeacherId==owner,ct);if(p is null||local is null)return Results.NotFound();if(p.Revision!=input.Revision)return Results.Conflict();if(!input.PreserveLocal)return Results.Conflict(new{message="Для теста сохраните текущую версию перед обновлением."});var backup=new Quiz{TeacherId=owner};var old=new SaveQuiz(local.Title,local.MaterialId,local.Questions.OrderBy(q=>q.Position).Select(q=>new QuestionInput(q.Type,q.Text,q.Points,q.ModelAnswer,q.Options.OrderBy(o=>o.Position).Select(o=>new OptionInput(o.Text,o.IsCorrect)).ToList())).ToList());TeachingEndpoints.Apply(backup,old with{Title=(local.Title+" — моя версия")[..Math.Min((local.Title+" — моя версия").Length,200)]});db.Quizzes.Add(backup);db.Questions.RemoveRange(local.Questions);TeachingEndpoints.Apply(local,JsonSerializer.Deserialize<SaveQuiz>(p.Snapshot)! with{MaterialId=local.MaterialId});db.Questions.AddRange(local.Questions);reference.SourceRevision=p.Revision;reference.Baseline=p.Snapshot;}else return Results.BadRequest();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.NoContent();});
 }
}
